CREATE OR REPLACE FUNCTION public.kora_nova_retail_resume(p_otp uuid, p_enlace uuid, p_cedula text, p_celular text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare s public.kora_nova_sources; v_origin text; hashes jsonb; v_count integer;
begin
 perform 1 from public.otp_codigos o where o.id=p_otp and o.enlace_registro_id=p_enlace and o.cedula=p_cedula and o.celular=p_celular and o.verificado and o.envio_aceptado_at is not null and o.envio_fallido_at is null and o.created_at>now()-interval '30 minutes';
 if not found then raise exception 'OTP_REQUIRED';end if;
 select origen_codigo into v_origin from public.enlaces_registro where id=p_enlace and activo and revoked_at is null;
 if v_origin !~ '^CK-0[1-9]$' or v_origin is null then raise exception 'OUTSIDE_PILOT';end if;
 select src.* into s from public.kora_nova_sources src join public.clientes c on c.id=src.cliente_id left join public.nova_retail_cases rc on rc.source_id=src.solicitud_id where c.cedula=p_cedula and c.celular=p_celular and src.registration->>'p_origen_codigo'=v_origin and src.revoked_at is null and rc.delivered_at is null order by src.submitted_at desc limit 1;
 if not found then return jsonb_build_object('found',false);end if;
 select jsonb_object_agg(tipo,sha256),count(*) into hashes,v_count from public.documentos_solicitud where solicitud_id=s.solicitud_id;

 return jsonb_build_object('found',true,'incomplete',v_count<>3,'sourceId',s.solicitud_id,'clientId',s.cliente_id,'hashes',coalesce(hashes,'{}'::jsonb),'sourceOtp',s.otp_id,'name',s.registration->>'p_nombre_completo','savedTypes',(select coalesce(jsonb_agg(tipo),'[]'::jsonb) from public.documentos_solicitud where solicitud_id=s.solicitud_id));
end $function$

CREATE OR REPLACE FUNCTION public.kora_nova_retail_seed_photos(p_source uuid, p_verified_otp uuid, p_subject text)
 RETURNS boolean
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare s public.kora_nova_sources; r public.nova_retail_photo_reviews; d public.documentos_solicitud;
begin
 select * into strict s from public.kora_nova_sources where solicitud_id=p_source and revoked_at is null;
 if (p_subject ~ '^[a-f0-9]{64}$') is not true then raise exception 'INVALID_SUBJECT';end if;
 perform 1 from public.otp_codigos o join public.enlaces_registro l on l.id=o.enlace_registro_id where o.id=p_verified_otp and o.verificado and o.cedula=s.registration->>'p_cedula' and o.celular=s.registration->>'p_celular' and l.origen_codigo=s.registration->>'p_origen_codigo' and l.activo and l.revoked_at is null and o.envio_aceptado_at is not null and o.envio_fallido_at is null and o.created_at>now()-interval '30 minutes';
 if not found then raise exception 'OTP_REQUIRED';end if;
 perform pg_advisory_xact_lock(hashtextextended('nova-photo:'||s.otp_id::text,0));
 insert into public.nova_retail_photo_reviews(otp_id,subject_hash) values(s.otp_id,p_subject) on conflict do nothing;
 select * into strict r from public.nova_retail_photo_reviews where otp_id=s.otp_id for update;
 if r.lease_until>now() then raise exception 'REVIEW_IN_PROGRESS';end if;
 for d in select * from public.documentos_solicitud where solicitud_id=s.solicitud_id loop
  if (r.hashes->>d.tipo is distinct from d.sha256) or not (r.results ? d.tipo) then
   r.results:=jsonb_set(r.results,array[d.tipo],'{"issues":["uncertain"],"status":"manual_pending"}');
  end if;
  r.hashes:=jsonb_set(r.hashes,array[d.tipo],to_jsonb(d.sha256));
 end loop;
 update public.nova_retail_photo_reviews set subject_hash=p_subject,results=r.results,hashes=r.hashes,updated_at=now() where otp_id=s.otp_id;
 return true;
end $function$

CREATE OR REPLACE FUNCTION public.proteger_otp_registro_seguro()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if new.enlace_registro_id is not null then
    if new.codigo_hash is null
      or new.codigo_hash !~ '^[A-Za-z0-9_-]{43}$' then
      raise exception 'codigo_hash_invalido';
    end if;
    new.codigo := 'HASHED';
  end if;
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.reservar_otp_registro_seguro(p_cedula text, p_celular text, p_enlace_registro_id uuid, p_codigo_hash text, p_expira_at timestamp with time zone)
 RETURNS TABLE(otp_id uuid)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_envios_celular integer;
  v_envios_enlace integer;
  v_otp_id uuid;
begin
  if p_cedula !~ '^[0-9]{6,12}$'
    or p_celular !~ '^3[0-9]{9}$'
    or p_codigo_hash !~ '^[A-Za-z0-9_-]{43}$'
    or p_expira_at <= now() then
    raise exception 'otp_reserva_invalida';
  end if;

  -- Todos los callers toman los locks en el mismo orden. Las reservas
  -- concurrentes para un mismo celular o enlace quedan serializadas dentro
  -- de la transacción que cuenta e inserta el OTP.
  perform pg_advisory_xact_lock(
    hashtextextended('otp:celular:' || p_celular, 0)
  );
  perform pg_advisory_xact_lock(
    hashtextextended('otp:enlace:' || p_enlace_registro_id::text, 0)
  );

  select count(*) into v_envios_celular
  from public.otp_codigos
  where celular = p_celular
    and enlace_registro_id is not null
    and envio_fallido_at is null
    and (
      (
        envio_aceptado_at is not null
        and created_at >= now() - interval '1 hour'
      )
      or (
        envio_aceptado_at is null
        and created_at >= now() - interval '10 minutes'
      )
    );
  if v_envios_celular >= 3 then
    raise exception 'otp_limite_celular';
  end if;

  select count(*) into v_envios_enlace
  from public.otp_codigos
  where enlace_registro_id = p_enlace_registro_id
    and envio_fallido_at is null
    and (
      (
        envio_aceptado_at is not null
        and created_at >= now() - interval '1 hour'
      )
      or (
        envio_aceptado_at is null
        and created_at >= now() - interval '10 minutes'
      )
    );
  if v_envios_enlace >= 60 then
    raise exception 'otp_limite_enlace';
  end if;

  insert into public.otp_codigos (
    cedula, celular, enlace_registro_id, codigo_hash,
    expira_at, intentos, verificado
  ) values (
    p_cedula, p_celular, p_enlace_registro_id, p_codigo_hash,
    p_expira_at, 0, false
  )
  returning id into v_otp_id;

  return query select v_otp_id;
end;
$function$
